import { createFileRoute } from '@tanstack/react-router';
import { useEffect } from 'react';
import { useRuntimeStore } from '../stores/runtimeStore';
import { RuntimeStateBadge } from '../components/RuntimeStateBadge';

export const Route = createFileRoute('/compact')({
  component: CompactRoute,
});

/**
 * Quick-interaction compact panel surface (per spec §11). Phase 1 ships only the
 * idle pill; the full transcript stream and PTT controls land in Phase 2.
 */
function CompactRoute() {
  const connect = useRuntimeStore((s) => s.connect);
  const disconnect = useRuntimeStore((s) => s.disconnect);

  useEffect(() => {
    connect();
    return () => disconnect();
  }, [connect, disconnect]);

  return (
    <section data-testid="route-compact" className="flex h-full items-center justify-center bg-thaddeus-mist p-4">
      <div className="w-full max-w-md rounded-2xl border border-slate-200 bg-white p-6 shadow-lg">
        <div className="flex items-center justify-between">
          <p className="text-sm font-medium text-thaddeus-ink">Sir Thaddeus</p>
          <RuntimeStateBadge />
        </div>
        <p className="mt-4 text-xs text-slate-500">Press your global shortcut to start a quick interaction.</p>
      </div>
    </section>
  );
}
